<script>
 import {onMount,untrack} from 'svelte';
 import {panViewport} from '../canvas-wheel.js';
 import {SvelteFlow,Background,Controls,MiniMap,BackgroundVariant,addEdge} from '@xyflow/svelte';
 import '@xyflow/svelte/dist/style.css';
 import {Plus,Undo2,Redo2,LayoutGrid,PanelLeftClose,PanelRightClose,X,Save,Sparkles,ArrowRight} from 'lucide-svelte';
 import StoryNode from './StoryNode.svelte';
 import GenerationStudio from './GenerationStudio.svelte';
 import ReferenceAssets from './ReferenceAssets.svelte';
 import {buildGraph,connectStory,disconnectStory,graphId} from '../canvas-model.js';
 import {composePrompts,wordCount,validateScene} from '../visual-model.js';
 let {project=$bindable(),characters=$bindable(),locations=$bindable(),assets=[],onassetschange,onnewscene,onopen,oncharacter,onlocation,notify}=$props();
 let nodes=$state.raw([]),edges=$state.raw([]),viewport=$state({x:20,y:40,zoom:.78}),loaded=$state(false),active=$state(null),left=$state(true),right=$state(true),undo=$state([]),redo=$state([]),connectSource=$state(''),connectTarget=$state(''),tab=$state('details'),showGeneration=$state(false),newEntity=$state(''),newName=$state(''),newDescription=$state(''),error=$state(''),promptType=$state('image'),applyTo=$state('');
 function captureCanvasWheel(element){
  const wheel=event=>{
   // Ctrl/pinch zoom remains owned by Svelte Flow. Pan before its wheel filters
   // so horizontal trackpad gestures work over cards as well as blank canvas.
   if(event.ctrlKey||event.metaKey||event.target.closest('input,textarea,select,[contenteditable="true"],video'))return;
   event.preventDefault();event.stopImmediatePropagation();
   viewport=panViewport(viewport,event,element.clientWidth,element.clientHeight);
  };
  element.addEventListener('wheel',wheel,{capture:true,passive:false});
  return {destroy(){element.removeEventListener('wheel',wheel,true);}};
 }
 const nodeTypes={story:StoryNode};
 let activeNode=$derived(nodes.find(n=>n.id===active)),entity=$derived(activeNode?.data.kind==='character'?characters.find(c=>c.id===activeNode.data.entityId):activeNode?.data.kind==='location'?locations.find(l=>l.id===activeNode.data.entityId):null),scene=$derived(project.scenes.find(s=>s.id===activeNode?.data.entityId));
 let selectedTheme=$derived(project.themes?.find(t=>t.id===activeNode?.data.entityId));
 let pipelineConnected=$derived.by(()=>{const kind=activeNode?.data.kind;if(!['prompt','image','video'].includes(kind))return true;const stages=['scene','prompt','image','video'],last=stages.indexOf(kind),id=activeNode.data.entityId;for(let i=1;i<=last;i++)if(!edges.some(e=>e.source===graphId(stages[i-1],id)&&e.target===graphId(stages[i],id)))return false;return true;});
 let scenePrompts=$derived(scene?composePrompts(scene,characters,locations,project.scenes[project.scenes.findIndex(s=>s.id===scene.id)-1],assets):null);
 let displayNodes=$derived(nodes.map(n=>{const d=n.data,c=characters.find(c=>c.id===d.entityId),l=locations.find(l=>l.id===d.entityId),s=project.scenes.find(s=>s.id===d.entityId),t=project.themes?.find(t=>t.id===d.entityId),reference=assets.find(a=>a.type===d.kind&&a.ownerId===d.entityId&&a.approved),image=assets.find(a=>a.id===s?.approvedImageId&&a.storyId===project.id&&a.ownerId===s.id),video=assets.find(a=>a.id===s?.approvedVideoId&&a.storyId===project.id);return {...n,data:{...d,title:d.kind==='theme'?t?.name:d.kind==='character'?c?.name:d.kind==='location'?l?.name:d.kind==='scene'?s?.title:d.kind==='prompt'?'Scene Director':d.kind==='image'?'Scene image':'Scene video',description:d.kind==='theme'?t?.description:d.kind==='character'?c?.description:d.kind==='location'?l?.description:d.kind==='scene'?s?.text:d.kind==='prompt'?'Character + location + action into three editable prompts.':d.kind==='image'?`${image?'Approved image':'Generate or import a moment'} · ${s?.title}`:`${video?'Saved motion asset':'Image to video or text to video'} · ${s?.title}`,image:d.kind==='theme'?assets.find(a=>a.id===t?.referenceAssetId)?.url:d.kind==='character'?reference?.url||c?.image:d.kind==='location'?reference?.url:d.kind==='image'?image?.url:d.kind==='video'?video?.mime?.startsWith('image/')?video.url:image?.url:null,mock:d.kind==='image'?image?.mock:d.kind==='video'?video?.mock:reference?.mock,meta:d.kind==='theme'?(t?.sceneIds?.length||0)+' connected scenes':d.kind==='scene'?`${wordCount(s?.text)} words · ${s?.choices.length||0} branches`:d.kind==='character'?'Reusable identity':d.kind==='location'?'Reusable environment':'Scene '+d.entityId,video:d.kind==='video'&&video?.mime?.startsWith('video/')?video.url:null,referenceUrl:d.kind==='character'?(reference?.url||(c?.referenceReady?(c.referenceSheet||'/images/'+c.id+'-turnaround.png'):null)):null,cast:d.kind==='scene'?characters.filter(c=>s?.characterIds?.includes(c.id)).map(c=>c.name):[],actions:d.kind==='scene'?s?.actions:null,dialogue:d.kind==='scene'?s?.dialogue:null,motionPrompt:d.kind==='video'?video?.prompt:null,open:()=>select(n.id)}};}));
 onMount(()=>{const base=buildGraph(project,characters,locations),saved=project.canvas||base;nodes=JSON.parse(JSON.stringify(saved.nodes)).filter(n=>base.nodes.some(b=>b.id===n.id)||['prompt','image','video'].includes(n.data.kind)&&project.scenes.some(s=>s.id===n.data.entityId));for(const n of base.nodes)if(!nodes.some(x=>x.id===n.id))nodes.push(n);edges=JSON.parse(JSON.stringify(saved.edges)).filter(e=>nodes.some(n=>n.id===e.source)&&nodes.some(n=>n.id===e.target));for(const e of base.edges)if(!edges.some(x=>x.source===e.source&&x.target===e.target))edges.push(e);if(saved.viewport)viewport=saved.viewport;active=graphId('scene',project.scenes[0].id);loaded=true;});
 $effect(()=>{if(!loaded)return;const clean=nodes.map(n=>({id:n.id,type:'story',position:{...n.position},data:{kind:n.data.kind,entityId:n.data.entityId}}));project.canvas={nodes:clean,edges:edges.map(e=>({id:e.id,source:e.source,target:e.target,label:e.label||''})),viewport:{...viewport}};});
 function snapshot(){return JSON.stringify({nodes,edges,scenes:project.scenes,themes:project.themes||[]});}
 function remember(){undo=[...undo.slice(-29),snapshot()];redo=[];}
 function restore(value){const v=JSON.parse(value);nodes=v.nodes;edges=v.edges;project.scenes=v.scenes;project.themes=v.themes||project.themes||[];}
 function back(){if(!undo.length)return;redo=[...redo,snapshot()];restore(undo.at(-1));undo=undo.slice(0,-1);}
 function forward(){if(!redo.length)return;undo=[...undo,snapshot()];restore(redo.at(-1));redo=redo.slice(0,-1);}
 function select(id){active=id;right=true;showGeneration=false;error='';const kind=nodes.find(n=>n.id===id)?.data.kind;tab=kind==='prompt'?'prompts':['image','video'].includes(kind)?'generation':'details';}
 function connect(connection){try{remember();const message=connectStory(project,nodes,connection.source,connection.target);edges=addEdge({...connection,id:crypto.randomUUID(),type:'default',style:'stroke:#879d00;stroke-width:2'},edges);syncLocation();notify(message);}catch(e){error=e.message;}}
 function syncLocation(){for(const s of project.scenes)s.location=locations.find(l=>l.id===s.locationId)?.name||'';}
 function removeEdge(edge){remember();const rest=edges.filter(e=>e.id!==edge.id);disconnectStory(project,nodes,edge,rest);edges=rest;syncLocation();}
 function arrange(){remember();nodes=nodes.map((n,i)=>({...n,position:{x:n.data.kind==='character'?0:n.data.kind==='location'?330:700+(i%3)*340,y:n.data.kind==='character'?nodes.filter(x=>x.data.kind==='character').findIndex(x=>x.id===n.id)*400:n.data.kind==='location'?nodes.filter(x=>x.data.kind==='location').findIndex(x=>x.id===n.id)*400:Math.floor(nodes.filter(x=>!['character','location'].includes(x.data.kind)).findIndex(x=>x.id===n.id)/3)*390}}));notify('Nodes arranged. Use Fit View to see the story.');}
 function addAsset(kind,id){if(id===null||id===undefined)return;if(nodes.some(n=>n.id===graphId(kind,id))){select(graphId(kind,id));return;}remember();nodes=[...nodes,{id:graphId(kind,id),type:'story',position:{x:Math.round(-viewport.x/viewport.zoom+100),y:Math.round(-viewport.y/viewport.zoom+100)},data:{kind,entityId:id}}];active=graphId(kind,id);}
 function pipeline(){if(!scene)return;remember();let all=[...nodes],links=[...edges],x=nodes.find(n=>n.id===graphId('scene',scene.id))?.position.x||700,y=nodes.find(n=>n.id===graphId('scene',scene.id))?.position.y||0;['prompt','image','video'].forEach((kind,i)=>{const id=graphId(kind,scene.id);if(!all.some(n=>n.id===id))all.push({id,type:'story',position:{x:x+(i+1)*340,y},data:{kind,entityId:scene.id}});const source=graphId(i===0?'scene':i===1?'prompt':'image',scene.id);if(!links.some(e=>e.source===source&&e.target===id))links.push({id:crypto.randomUUID(),source,target:id});});nodes=all;edges=links;notify('Scene → prompt → image → video pipeline added');}
 function create(){if(!newName.trim()||!newDescription.trim())return;const e=newEntity==='character'?oncharacter(newName,newDescription):onlocation(newName,newDescription);addAsset(newEntity,e.id);newEntity='';newName='';newDescription='';}
 function finalize(next=false){error=validateScene(scene);if(error)return;scene.finalized=true;scene.status='Ready for review';notify('Scene finalized');if(next){const id=onnewscene(scene.id);addAsset('scene',id);right=true;}}
 function updateNodePosition(event){nodes=event.nodes?nodes.map(n=>{const changed=event.nodes.find(x=>x.id===n.id);return changed?{...n,position:changed.position}:n;}):nodes;}
</script>
<section class="story-canvas-shell" aria-label="Visual storytelling canvas">
 <div class="canvas-topbar"><div><span class="eyebrow">STORY SPACE</span><strong>{project.title}</strong></div><div><button class="icon" aria-label="Toggle asset library" onclick={()=>left=!left}><PanelLeftClose size={17}/></button><button class="icon" aria-label="Undo canvas change" disabled={!undo.length} onclick={back}><Undo2 size={16}/></button><button class="icon" aria-label="Redo canvas change" disabled={!redo.length} onclick={forward}><Redo2 size={16}/></button><button class="text-button" onclick={arrange}><LayoutGrid size={14}/> Arrange</button><button class="button primary" onclick={()=>{const id=onnewscene();addAsset('scene',id);right=true;}}><Plus size={14}/> Scene</button><button class="icon" aria-label="Toggle canvas properties" onclick={()=>right=!right}><PanelRightClose size={17}/></button></div></div>
 <div class="canvas-body" class:library-closed={!left} class:properties-closed={!right}>
 {#if left}<aside class="canvas-library"><div class="canvas-library-title"><h3>Asset library</h3><span>REUSABLE</span></div><p>Add a card, then connect its handle to a scene.</p><button class="canvas-library-add" onclick={()=>newEntity='character'}><Plus size={13}/> Create character</button><button class="canvas-library-add" onclick={()=>newEntity='location'}><Plus size={13}/> Create location</button><details open><summary>Characters · {characters.length}</summary>{#each characters as c}<button onclick={()=>addAsset('character',c.id)}>{#if c.image}<img src={c.image} alt=""/>{:else}<span>{c.name[0]}</span>{/if}<span>{c.name}</span><Plus size={12}/></button>{/each}</details><details><summary>Locations · {locations.length}</summary>{#each locations as l}<button onclick={()=>addAsset('location',l.id)}><span>⌂</span><span>{l.name}</span><Plus size={12}/></button>{/each}</details></aside>{/if}
 <div class="canvas-center"><div class="flow-wrap" use:captureCanvasWheel>{#if loaded}<SvelteFlow nodes={displayNodes} bind:edges bind:viewport {nodeTypes} minZoom={.12} maxZoom={1.6} panOnScroll={true} panOnScrollMode="free" zoomOnScroll={false} zoomActivationKey="Control" zoomOnPinch={true} onconnect={connect} onnodeclick={({node})=>select(node.id)} onnodedragstart={remember} onnodedragstop={updateNodePosition} deleteKey={null} fitView={false} defaultEdgeOptions={{style:'stroke:#829a00;stroke-width:2',type:'default'}}><Background variant={BackgroundVariant.Dots} gap={22} size={1} color="#ccd1c1"/><Controls/><MiniMap pannable zoomable nodeColor="#dfff00"/></SvelteFlow>{/if}</div><div class="mobile-node-navigator"><label>Inspect node<select value={active} onchange={e=>select(e.currentTarget.value)}>{#each displayNodes as n}<option value={n.id}>{n.data.kind} · {n.data.title}</option>{/each}</select></label></div><div class="canvas-connect-panel"><span>Accessible connection controls</span><div><select aria-label="Connection source" bind:value={connectSource}><option value="">From node…</option>{#each displayNodes as n}<option value={n.id}>{n.data.kind} · {n.data.title}</option>{/each}</select><ArrowRight size={13}/><select aria-label="Connection destination" bind:value={connectTarget}><option value="">To node…</option>{#each displayNodes as n}<option value={n.id}>{n.data.kind} · {n.data.title}</option>{/each}</select><button class="button secondary" onclick={()=>connect({source:connectSource,target:connectTarget})}>Connect</button></div></div></div>
 {#if right}<aside class="canvas-properties"><div class="canvas-properties-title"><span>{activeNode?.data.kind||'STORY'} PROPERTIES</span><button class="icon" aria-label="Close canvas properties" onclick={()=>right=false}><X size={16}/></button></div>
 {#if activeNode}<div class="node-position-fields"><label>X<input type="number" value={activeNode.position.x} onfocus={remember} oninput={e=>nodes=nodes.map(n=>n.id===active?{...n,position:{...n.position,x:Number(e.currentTarget.value)}}:n)}/></label><label>Y<input type="number" value={activeNode.position.y} onfocus={remember} oninput={e=>nodes=nodes.map(n=>n.id===active?{...n,position:{...n.position,y:Number(e.currentTarget.value)}}:n)}/></label></div>{/if}
 {#if newEntity}<h3>Create {newEntity}</h3><label class="director-field">Name<input bind:value={newName}/></label><label class="director-field">Description<textarea bind:value={newDescription}></textarea></label><button class="button primary" onclick={create}>Create saved {newEntity}</button><button class="text-button" onclick={()=>newEntity=''}>Cancel</button>
 {:else if activeNode?.data.kind==='theme'&&selectedTheme}<h3>{selectedTheme.name}</h3><label class="director-field">Name<input bind:value={selectedTheme.name}/></label><label class="director-field">Description<textarea bind:value={selectedTheme.description}></textarea></label><p>Connect this theme to the scenes that explore it.</p>{#each project.scenes as sc}<label class="reference-coverage"><input type="checkbox" checked={selectedTheme.sceneIds?.includes(sc.id)} onchange={()=>{const source=graphId('theme',selectedTheme.id),target=graphId('scene',sc.id),edge=edges.find(e=>e.source===source&&e.target===target);if(edge)removeEdge(edge);else connect({source,target});}}/>{sc.title}</label>{/each}{:else if entity}<h3>{entity.name}</h3><label class="director-field">Name<input bind:value={entity.name}/></label><label class="director-field">Description<textarea bind:value={entity.description}></textarea></label>{#if activeNode.data.kind==='character'}<label class="director-field">Appearance<textarea bind:value={entity.appearance}></textarea></label><label class="director-field">Personality<textarea bind:value={entity.personality}></textarea></label><label class="director-field">Clothing<textarea bind:value={entity.clothing}></textarea></label>{:else}<label class="director-field">Atmosphere<textarea bind:value={entity.atmosphere}></textarea></label>{/if}<ReferenceAssets {entity} type={activeNode.data.kind} {assets} {onassetschange} {notify} storyId={project.id}/><label class="director-field">Apply approved reference to scene<select bind:value={applyTo}><option value="">Future generations only</option>{#each project.scenes as s}<option value={String(s.id)}>{s.title}</option>{/each}</select></label><button class="button secondary" onclick={()=>{const ref=assets.find(a=>a.type===activeNode.data.kind&&a.ownerId===entity.id&&a.approved),target=project.scenes.find(s=>String(s.id)===applyTo);if(!ref||!target){error='Choose a scene and approve a reference first.';return;}target.referenceBindings={...target.referenceBindings,[activeNode.data.kind+':'+entity.id]:ref.id};notify('Reference version applied to future generations of this scene. Existing image preserved.');}}>Apply version</button><p class="reference-help">Changing a reference affects future prompts. Existing scene images remain intact. Connect this reference only to scenes you want to use it.</p>
 {:else if scene&&!pipelineConnected}<h3>Connect this stage</h3><p>Connect scene → AI prompt → image → video to activate this node. Existing images are preserved.</p>{:else if scene}<span class="canvas-scene-number">SCENE {String(scene.id).padStart(2,'0')}</span><h3>{scene.title}</h3><div class="canvas-property-tabs"><button class:active={tab==='details'} onclick={()=>tab='details'}>Scene</button><button class:active={tab==='prompts'} onclick={()=>tab='prompts'}>Prompts</button><button class:active={tab==='generation'} onclick={()=>tab='generation'}>Generate</button></div>
 {#if tab==='details'}<label class="director-field">Title<input bind:value={scene.title}/></label><div class="connected-cast">{#each characters.filter(c=>scene.characterIds?.includes(c.id)) as c}<span>{#if c.image}<img src={c.image} alt=""/>{/if}{c.name}</span>{/each}</div><p class="canvas-setting">{[scene.locationId,...(scene.additionalLocationIds||[])].map(id=>locations.find(l=>l.id===id)?.name).filter(Boolean).join(' + ')||'Connect a location node'}</p><label class="director-field">Scene description<textarea class="canvas-description" bind:value={scene.text}></textarea></label><span class="word-counter" class:word-ready={wordCount(scene.text)>=100}>{wordCount(scene.text)} / 100 words</span><label class="director-field">Actions<textarea bind:value={scene.actions}></textarea></label><label class="director-field">Dialogue<textarea bind:value={scene.dialogue}></textarea></label><label class="director-field">Emotions<textarea bind:value={scene.emotions}></textarea></label><label class="director-field">Camera angle<input bind:value={scene.camera} placeholder="Eye-level medium wide"/></label><label class="director-field">Atmosphere<textarea bind:value={scene.atmosphere}></textarea></label><div class="prompt-actions"><button class="button secondary" onclick={()=>finalize()}>Finalize scene</button><button class="button primary" onclick={()=>finalize(true)}>Next Moment</button></div><button class="text-button canvas-pipeline-button" onclick={pipeline}><Sparkles size={13}/> Add generation pipeline</button><button class="text-button" onclick={()=>onopen(scene.id)}>Open full Scene Director ↗</button>
 {:else if tab==='prompts'}<p>Local prompt composition, no AI service called. Rebuild updates this scene’s prompt without recreating its characters.</p><label class="director-field">Prompt type<select bind:value={promptType}><option value="image">Text to image</option><option value="imageToVideo">Image to video</option><option value="textToVideo">Text to video</option></select></label><label class="director-field">Editable prompt<textarea class="canvas-prompt" value={scene.promptOverrides?.[promptType]??scenePrompts[promptType]} oninput={e=>scene.promptOverrides={...scene.promptOverrides,[promptType]:e.currentTarget.value}}></textarea></label><button class="button secondary" onclick={()=>scene.promptOverrides={...scene.promptOverrides,[promptType]:undefined}}>Rebuild prompt</button>
 {:else}{#key scene.id}<GenerationStudio storyId={project.id} {scene} kind={activeNode?.data.kind==='video'?'image-to-video':'scene'} prompt={activeNode?.data.kind==='video'?(scene.promptOverrides?.imageToVideo??scenePrompts.imageToVideo):(scene.promptOverrides?.image??scenePrompts.image)} {assets} {onassetschange} {notify}/>{/key}{/if}
 {/if}
 {#if error}<p role="alert" class="director-error">{error}</p>{/if}<details class="canvas-connections"><summary>Connections · {edges.length}</summary>{#each edges.filter(e=>e.source===active||e.target===active) as e}<div><span>{e.source} → {e.target}</span><button aria-label={`Remove connection ${e.id}`} onclick={()=>removeEdge(e)}><X size={12}/></button></div>{/each}</details></aside>{/if}
 </div><nav class="canvas-timeline" aria-label="Storyboard scene navigator">{#each project.scenes as s,i}<button class:active={activeNode?.data.entityId===s.id} onclick={()=>{select(graphId('scene',s.id));}}><span>{String(i+1).padStart(2,'0')}</span>{s.title}<small>{s.choices.length} branches</small></button>{/each}</nav>
</section>
